SELECT A.id, A.name, B.os_type, B.id AS config_Id, B.status, B.config FROM sdk_customer_channel A LEFT JOIN sdk_customer_channel_config B ON A.id = B.sdk_customer_channel_id ORDER BY A.id DESC
limit #{limit}
offset #{offset}

mapper.update:
UPDATE sdk_customer_channel
SET name = #{name}
WHERE id = #{id}
